    "consent.switchDetail":
      "AI ಅನ್ನು ತರಬೇತಿಗೊಳಿಸಲು ಹೆಸರು ತೆಗೆದ ನಿಮ್ಮ ತೀರ್ಪುಗಳು ಮತ್ತು ರೇಟಿಂಗ್‌ಗಳನ್ನು Judge ಬಳಸಲು ಅವಕಾಶ ನೀಡುತ್ತದೆ. ನೀವು ಆನ್ ಮಾಡದ ಹೊರತು ಆಫ್ ಆಗಿರುತ್ತದೆ.",
    "consent.sensitiveTitle": "ಪ್ರಾರಂಭಿಸುವ ಮೊದಲು",
    "consent.sensitiveBody":
      "ನನ್ನ ಬರಹದಲ್ಲಿ ಆರೋಗ್ಯ ಅಥವಾ ಸಂಬಂಧಗಳಂತಹ ಖಾಸಗಿ ವಿವರಗಳು ಇರಬಹುದು. Judge ಹೆಸರುಗಳನ್ನು ತೆಗೆದು ಅದನ್ನು ನನ್ನ ತೀರ್ಪು ಬರೆಯಲು ಹೊರಗಿನ AI ಸೇವಾ ಪೂರೈಕೆದಾರರಿಗೆ ಕಳುಹಿಸುತ್ತದೆ, ಮತ್ತು ನಾನು ತೆಗೆಯುವವರೆಗೆ ಇಟ್ಟುಕೊಳ್ಳುತ್ತದೆ.",
    "consent.sensitiveContinue": "ಮುಂದುವರಿಸಿ",
