    "deletePage.title": "ನಿಮ್ಮ Judge ಖಾತೆಯನ್ನು ಅಳಿಸಿ",
    "deletePage.lead":
      "Judge ಎಂಬುದು Aytu Tuna ಅವರ ಆ್ಯಪ್. ಆ್ಯಪ್‌ನಲ್ಲಿ ಅಥವಾ ವೆಬ್‌ಸೈಟ್‌ನಲ್ಲಿ ನೀವೇ ಯಾವಾಗ ಬೇಕಾದರೂ ಖಾತೆ ಮತ್ತು ಅದರ ಡೇಟಾ ಅಳಿಸಬಹುದು.",
    "deletePage.appTitle": "ಆ್ಯಪ್‌ನಲ್ಲಿ",
    "deletePage.app": "Judge ತೆರೆಯಿರಿ, ಖಾತೆಗೆ ಹೋಗಿ, ಖಾತೆ ಅಳಿಸಿ ಟ್ಯಾಪ್ ಮಾಡಿ ಮತ್ತು ದೃಢೀಕರಿಸಿ.",
    "deletePage.webTitle": "ವೆಬ್‌ಸೈಟ್‌ನಲ್ಲಿ",
    "deletePage.web": "okjudge.com ನಲ್ಲಿ ಸೈನ್ ಇನ್ ಮಾಡಿ, ಖಾತೆ ತೆರೆಯಿರಿ, ಖಾತೆ ಅಳಿಸಿ ಆಯ್ಕೆಮಾಡಿ ಮತ್ತು ದೃಢೀಕರಿಸಿ.",
    "deletePage.removedTitle": "ಏನು ಅಳಿಸಲಾಗುತ್ತದೆ",
    "deletePage.removed":
      "ನಿಮ್ಮ ಖಾತೆ, ಸೈನ್-ಇನ್ ದಾಖಲೆಗಳು, ಕ್ರೆಡಿಟ್‌ಗಳು, ಪ್ಲಾನ್ ಮತ್ತು ಬಳಕೆಯ ಘಟನೆಗಳು ಅಳಿಸಲ್ಪಡುತ್ತವೆ. ನಿಮ್ಮ ತೀರ್ಪುಗಳು ಮತ್ತು ಪ್ರಕರಣಗಳಲ್ಲಿನ ನಿಮ್ಮ ಪಕ್ಷಗಳು ತೆಗೆಯಲ್ಪಡುತ್ತವೆ: ಮೂಲ ಬರಹ ಮತ್ತು ಹೆಸರುಗಳು ತಕ್ಷಣ ಅಳಿಸಲ್ಪಡುತ್ತವೆ, ಹೆಸರು ತೆಗೆದ ಬರಹ ಮತ್ತು ತೀರ್ಪು 30 ದಿನಗಳ ನಂತರ (ಪ್ರಕರಣದಲ್ಲಿ, ಅದರಲ್ಲಿರುವ ಎಲ್ಲರೂ ತೆಗೆದುಹಾಕಿದ 30 ದಿನಗಳ ನಂತರ).",
    "deletePage.keptTitle": "ನಾವು ಏನು ಇಟ್ಟುಕೊಳ್ಳುತ್ತೇವೆ",
    "deletePage.kept":
      "ತೆಗೆದ ತೀರ್ಪುಗಳ ಫಲಿತಾಂಶ ಮತ್ತು ದಿನಾಂಕಗಳು, ಬರಹ ಅಥವಾ ಹೆಸರುಗಳಿಲ್ಲದೆ. ನಿಮ್ಮ ರೇಟಿಂಗ್‌ಗಳು, ನಿಮ್ಮತ್ತ ಬರದಂತೆ ಯಾದೃಚ್ಛಿಕ ID ಗೆ ಸರಿಸಲ್ಪಟ್ಟು. ನಿಮ್ಮ ಒಪ್ಪಿಗೆ ದಾಖಲೆಗಳು 6 ವರ್ಷ, ನಿಮಗೆ ಯಾವುದೇ ಕೊಂಡಿ ಇಲ್ಲದೆ. ನಿಮ್ಮ ಖಾತೆ ಇಲ್ಲದ ಸಾಧನ ದಾಖಲೆ, ಗರಿಷ್ಠ 180 ದಿನ. ತೆಗೆದದ್ದರ ಪಟ್ಟಿ, ID ಮತ್ತು ದಿನಾಂಕಗಳೊಂದಿಗೆ ಆದರೆ ಪಠ್ಯ ಇಲ್ಲದೆ, 90 ದಿನ. ಉಚಿತ ಕ್ರೆಡಿಟ್‌ಗಳ ಪುನರಾವರ್ತಿತ ದುರುಪಯೋಗ ತಡೆಯಲು ನಿಮ್ಮ ಇಮೇಲ್‌ನ ಸಂಕೇತ ರೂಪ. ಬ್ಯಾಕಪ್‌ಗಳಲ್ಲಿ ಹಳೆಯ ಪ್ರತಿಗಳು ಗರಿಷ್ಠ 14 ದಿನ ಇರುತ್ತವೆ.",
    "deletePage.mailTitle": "ಇಮೇಲ್ ಮೂಲಕ ಕೇಳಿ",
