    "appeal.generic.overturned": "ಹೊಸ ವಿವರದಿಂದ ಫಲಿತಾಂಶ ಉಲ್ಟಾ ಆಯಿತು.",
    "appeal.generic.changed": "ಹೊಸ ವಿವರದಿಂದ ತೀರ್ಪು ಬದಲಾಯಿತು.",
    "appeal.previous": "ಹಿಂದಿನ ತೀರ್ಪು",
    "appeal.failed": "ಮರುತೀರ್ಪು ಆಗಲಿಲ್ಲ. ನಿಮ್ಮ ಕ್ರೆಡಿಟ್ ವಾಪಸ್ ಬಂದಿದೆ; ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಬಹುದು.",
    "appeal.refused": "ಆ ವಿವರದೊಂದಿಗೆ ಮರುತೀರ್ಪು ಕೊಡಲು ತೀರ್ಪುಗಾರರು ಒಪ್ಪಲಿಲ್ಲ. ನಿಮ್ಮ ಕ್ರೆಡಿಟ್ ವಾಪಸ್ ಬಂದಿದೆ.",
    "appeal.history": "ತೀರ್ಪಿನ ಇತಿಹಾಸ",
    "faq.both.q": "ಎದುರಿನವರೂ ತಮ್ಮ ಕಡೆಯ ಮಾತು ಹೇಳಬಹುದೇ?",
    "faq.both.a":
      "ಹೌದು, ನೀವು ಸೈನ್ ಇನ್ ಮಾಡಿದ ಮೇಲೆ. “ಎರಡೂ ಕಡೆ” ಆರಿಸಿ, ಅವರಿಗೆ ಕಳುಹಿಸಲು ನಿಮಗೆ ಒಂದು ಖಾಸಗಿ ಲಿಂಕ್ ಸಿಗುತ್ತದೆ. ಅವರು ಖಾತೆ ಇಲ್ಲದೆಯೇ ತಮ್ಮ ಕಡೆಯ ಮಾತು ಬರೆಯುತ್ತಾರೆ, ಮತ್ತು ತೀರ್ಪು ಬರುವವರೆಗೂ ನಿಮ್ಮಲ್ಲಿ ಯಾರಿಗೂ ಇನ್ನೊಬ್ಬರ ಬರಹ ಕಾಣುವುದಿಲ್ಲ. ಯಾವಾಗ ಬೇಕಾದರೂ ನಿಮ್ಮ ಕಡೆಯ ಮಾತಿನ ಮೇಲೆಯೇ ತೀರ್ಪು ಪಡೆಯಬಹುದು, ಮತ್ತು ಲಿಂಕ್ 7 ದಿನಗಳ ನಂತರ ಕೆಲಸ ಮಾಡುವುದಿಲ್ಲ.",
    "faq.both.premium":
      "ಕೇಸ್‌ಗೆ 1 ತೀರ್ಪು ಖರ್ಚಾಗುತ್ತದೆ, ಅವರು ಉತ್ತರಿಸದಿದ್ದರೆ ಅದು ವಾಪಸ್ ಬರುತ್ತದೆ. ತೀರ್ಪಿನ ನಂತರ ನಿಮ್ಮಲ್ಲಿ ಪ್ರತಿಯೊಬ್ಬರೂ ಒಮ್ಮೆ ಹೆಚ್ಚಿನ ವಿವರ ಸೇರಿಸಿ ಮರುತೀರ್ಪು ಪಡೆಯಬಹುದು (1 ತೀರ್ಪು).",
    "faq.evidence.q": "ನಾನು ಸ್ಕ್ರೀನ್‌ಶಾಟ್ ಸೇರಿಸಬಹುದೇ?",
    "faq.evidence.a":
      "ಹೌದು, ಪ್ರತಿ ಕಡೆಗೆ ಗರಿಷ್ಠ ಮೂರು, ಉದಾಹರಣೆಗೆ ಒಂದು ಚಾಟ್ ಅಥವಾ ರಸೀದಿ. ಪ್ರತಿ ಚಿತ್ರದ ಪಠ್ಯ ಓದಲು ಅದು ಒಮ್ಮೆ ಹೊರಗಿನ AI ಸೇವೆಗೆ ಹೋಗುತ್ತದೆ. ತೀರ್ಪುಗಾರರು ಹೆಸರುಗಳನ್ನು ಮರೆಮಾಡಿದ ಆವೃತ್ತಿಯನ್ನು ನೋಡುತ್ತಾರೆ. ಚಿತ್ರದಿಂದ ಓದಿದ ಪಠ್ಯವನ್ನು ನಿಮ್ಮ ಮೂಲ ಪಠ್ಯದ ಜೊತೆ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿ ಇಟ್ಟುಕೊಳ್ಳುತ್ತೇವೆ; ಚಿತ್ರವನ್ನೇ ಎಂದಿಗೂ ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ. ಸ್ಕ್ರೀನ್‌ಶಾಟ್‌ಗಳನ್ನು ಕತ್ತರಿಸಿರಬಹುದು ಅಥವಾ ಸಂದರ್ಭದಿಂದ ಹೊರತೆಗೆದಿರಬಹುದು, ಹಾಗಾಗಿ ತೀರ್ಪುಗಾರರು ಅವುಗಳನ್ನು ಬಲವಾದ ಪುರಾವೆ ಎಂದು ಪರಿಗಣಿಸುತ್ತಾರೆ, ಅಂತಿಮ ಸಾಬೀತು ಎಂದಲ್ಲ.",
    "about.casesTitle": "ಎರಡೂ ಕಡೆಯ ಮಾತು ಕೇಳುವುದು",
    "about.cases1":
      "ಎರಡು ಕಡೆಯ ಕೇಸ್‌ಗಳು: ಸೈನ್ ಇನ್ ಮಾಡಿ, ನಿಮ್ಮ ಕಡೆಯ ಮಾತು ಬರೆದು ಖಾಸಗಿ ಲಿಂಕ್ ಕಳುಹಿಸಿ. ಎದುರಿನವರು ನಿಮ್ಮದನ್ನು ನೋಡದೆಯೇ ತಮ್ಮದನ್ನು ಬರೆಯುತ್ತಾರೆ, ಮತ್ತು ತೀರ್ಪುಗಾರರು ಎರಡನ್ನೂ ತೂಗಿ ನೋಡುತ್ತಾರೆ: ಇಬ್ಬರೂ ಯಾವುದನ್ನು ಒಪ್ಪುತ್ತಾರೆ, ಯಾವುದರ ಬಗ್ಗೆ ತಕರಾರು ಇದೆ, ಮತ್ತು ಯಾವ ಪುರಾವೆ ತೀರ್ಪನ್ನು ಬದಲಿಸಬಹುದು.",
    "about.cases2": "7 ದಿನಗಳ ಒಳಗೆ ಯಾರೂ ಉತ್ತರಿಸದಿದ್ದರೆ ಲಿಂಕ್ ಕೆಲಸ ಮಾಡುವುದಿಲ್ಲ. ಆದರೂ ನಿಮ್ಮ ಕಡೆಯ ಮಾತಿನ ಮೇಲೆಯೇ ತೀರ್ಪು ಪಡೆಯಬಹುದು.",
    "about.premiumTitle": "ಹೆಚ್ಚುವರಿ ಸೌಲಭ್ಯಗಳು",
    "about.premium2": "ಪುರಾವೆ: ಚಾಟ್ ಅಥವಾ ದಾಖಲೆಗಳ ಸ್ಕ್ರೀನ್‌ಶಾಟ್ ಸೇರಿಸಿ. ಅವುಗಳಲ್ಲಿನ ಪಠ್ಯವನ್ನು ಓದಿ, ಹೆಸರುಗಳನ್ನು ಮರೆಮಾಡಿ, ಚಿತ್ರವನ್ನು ಬಿಸಾಡುತ್ತೇವೆ.",
    "about.premium3":
      "ಮರುಪರಿಶೀಲನೆ: ತೀರ್ಪಿನ ನಂತರ ಪ್ರತಿಯೊಬ್ಬರೂ ಒಮ್ಮೆ ಹೆಚ್ಚಿನ ವಿವರ ಸೇರಿಸಬಹುದು. ತೀರ್ಪುಗಾರರು ಎಲ್ಲವನ್ನೂ ಮತ್ತೆ ನೋಡಿ, ತೀರ್ಪು ಹಾಗೆಯೇ ಇದೆಯೇ, ಉಲ್ಟಾ ಆಯಿತೇ ಅಥವಾ ಬದಲಾಯಿತೇ ಎಂದು ಹೇಳುತ್ತಾರೆ. ಹಿಂದಿನ ತೀರ್ಪುಗಳನ್ನು ಈಗಲೂ ನೋಡಬಹುದು.",
    "about.premium4":
      "ಎರಡು ಕಡೆಯ ಕೇಸ್‌ಗೆ 1 ತೀರ್ಪು ಖರ್ಚಾಗುತ್ತದೆ. ನೀವು ಲಿಂಕ್ ಕಳುಹಿಸಿದಾಗ ಅದನ್ನು ಕಾಯ್ದಿರಿಸಲಾಗುತ್ತದೆ, 7 ದಿನಗಳ ಒಳಗೆ ಯಾರೂ ಉತ್ತರಿಸದಿದ್ದರೆ ವಾಪಸ್ ಬರುತ್ತದೆ.",
    "pricing.premium.f5": "ಸ್ಕ್ರೀನ್‌ಶಾಟ್ ಪುರಾವೆ, ಓದಿದ ನಂತರ ಬಿಸಾಡಲಾಗುತ್ತದೆ, ಹೆಚ್ಚುವರಿ ಶುಲ್ಕವಿಲ್ಲ",
    "pricing.premium.f6": "ತೀರ್ಪಿನ ನಂತರ ಹೆಚ್ಚಿನ ವಿವರ ಸೇರಿಸಿ ಮರುತೀರ್ಪು ಪಡೆಯಿರಿ (1 ತೀರ್ಪು)",
    "pricing.premium.f7": "ಎರಡೂ ಕಡೆಯ ಮಾತು ಕೇಳಿ: ಎದುರಿನವರಿಗೆ ಅವರ ಮಾತು ಹೇಳಲು ಖಾಸಗಿ ಲಿಂಕ್ ಕಳುಹಿಸಿ",
    "langToggle.toTr": "Türkçeye geç",
    "langToggle.toEn": "Switch to English",
