    "error.names_unavailable": "ಈಗ ಹೆಸರುಗಳನ್ನು ಉಳಿಸಲು ಆಗುತ್ತಿಲ್ಲ. ಸ್ವಲ್ಪ ಸಮಯದ ನಂತರ ಪ್ರಯತ್ನಿಸಿ.",
    "error.update_required": "ಈ ಪ್ರಕರಣದಲ್ಲಿ ಎರಡಕ್ಕಿಂತ ಹೆಚ್ಚು ಪಕ್ಷಗಳಿವೆ. ತೆರೆಯಲು ಆ್ಯಪ್ ಅಪ್‌ಡೇಟ್ ಮಾಡಿ.",
    "verdict.remove": "ಈ ತೀರ್ಪನ್ನು ತೆಗೆದುಹಾಕಿ",
    "verdict.remove.confirm":
      "ನೀವು ಬರೆದದ್ದು, ಹೆಸರುಗಳು ಮತ್ತು ಪ್ರದರ್ಶನ ಹೆಸರುಗಳನ್ನು ತೆಗೆದುಹಾಕಬೇಕೇ? ಹಂಚಿಕೆ ಲಿಂಕ್ ಮತ್ತು ಅದರ ಪೂರ್ವವೀಕ್ಷಣೆ ಚಿತ್ರ ಎಲ್ಲರಿಗೂ ಲೋಡ್ ಆಗುವುದು ನಿಲ್ಲುತ್ತದೆ (ಚಾಟ್‌ಗಳಲ್ಲಿ ಈಗಾಗಲೇ ಹಾಕಿರುವ ಪೂರ್ವವೀಕ್ಷಣೆಗಳು ಆ ಆ್ಯಪ್‌ಗಳು ರಿಫ್ರೆಶ್ ಮಾಡುವವರೆಗೂ ಕಾಣಬಹುದು). ಇದನ್ನು ವಾಪಸ್ ಪಡೆಯಲು ಆಗುವುದಿಲ್ಲ.",
    "verdict.remove.yes": "ಹೌದು, ತೆಗೆದುಹಾಕಿ",
    "verdict.removed": "ತೆಗೆದುಹಾಕಲಾಗಿದೆ. ಲಿಂಕ್ ಈಗ ಕೆಲಸ ಮಾಡುವುದಿಲ್ಲ.",
    "verdict.removeFailed": "ಈಗ ತೆಗೆದುಹಾಕಲು ಆಗಲಿಲ್ಲ. ಇನ್ನೊಮ್ಮೆ ಪ್ರಯತ್ನಿಸುತ್ತೀರಾ?",
    "case.remove": "ಈ ಕೇಸ್ ತೆಗೆದುಹಾಕಿ",
    "case.remove.confirm":
      "ಈ ಕೇಸ್‌ನಿಂದ ನಿಮ್ಮ ಮೂಲ ಪಠ್ಯ, ಹೆಸರುಗಳು ಮತ್ತು ನಿಮ್ಮ ಪ್ರದರ್ಶನ ಹೆಸರನ್ನು ತೆಗೆದುಹಾಕಬೇಕೇ? ಕೇಸ್‌ನ ಹಂಚಿಕೆ ಲಿಂಕ್‌ಗಳು ಎಲ್ಲರಿಗೂ ಕೆಲಸ ಮಾಡುವುದನ್ನು ನಿಲ್ಲಿಸುತ್ತವೆ (ಚಾಟ್‌ಗಳಲ್ಲಿ ಈಗಾಗಲೇ ಹಾಕಿರುವ ಪೂರ್ವವೀಕ್ಷಣೆಗಳು ಆ ಆ್ಯಪ್‌ಗಳು ರಿಫ್ರೆಶ್ ಮಾಡುವವರೆಗೂ ಕಾಣಬಹುದು). ಇದನ್ನು ವಾಪಸ್ ಪಡೆಯಲು ಆಗುವುದಿಲ್ಲ.",
    "case.remove.yes": "ಹೌದು, ತೆಗೆದುಹಾಕಿ",
