    "terms.title": "ಬಳಕೆಯ ನಿಯಮಗಳು",
    "terms.kicker": "ನಿಯಮಗಳ ಸಾರ",
    "terms.lead":
      "ಸಂಕ್ಷಿಪ್ತವಾಗಿ: Judge ವಯಸ್ಕರಿಗಾಗಿ, ಮೋಜು ಮತ್ತು ಸ್ಪಷ್ಟವಾದ ಯೋಚನೆಗಾಗಿ, ಮತ್ತು AI ತಪ್ಪಾಗಬಹುದು. ನೀವು ಯಾರ ಬಗ್ಗೆ ಬರೆಯುತ್ತೀರೋ ಅವರೊಂದಿಗೆ ನ್ಯಾಯಯುತವಾಗಿ ವರ್ತಿಸಿ.",
    "terms.updated": "ಕೊನೆಯ ಬಾರಿ ನವೀಕರಿಸಿದ್ದು: {date}",
    "terms.whoTitle": "Judge ಯಾರು ಬಳಸಬಹುದು",
    "terms.who":
      "Judge 18 ವರ್ಷ ಮತ್ತು ಮೇಲ್ಪಟ್ಟವರಿಗೆ ಮಾತ್ರ. ಬಳಸುವ ಮೂಲಕ ನೀವು ಹಾಗಿದ್ದೀರಿ ಎಂದು ದೃಢೀಕರಿಸುತ್ತೀರಿ. ಒಂದು ಖಾತೆ 18 ವರ್ಷದೊಳಗಿನವರದ್ದು ಎಂದು ತಿಳಿದರೆ, ನಾವು ಅದನ್ನು ಮುಚ್ಚುತ್ತೇವೆ.",
    "terms.whatTitle": "Judge ಎಂದರೇನು",
    "terms.what":
      "Judge ದೈನಂದಿನ ವಾದಗಳ ಮೇಲೆ AI ತೀರ್ಪುಗಳನ್ನು ನೀಡುತ್ತದೆ, ಮೋಜಿಗಾಗಿ ಮತ್ತು ಸ್ವಲ್ಪ ಸ್ಪಷ್ಟವಾಗಿ ಯೋಚಿಸಲು. ಇದು ಕಾನೂನು, ವೈದ್ಯಕೀಯ ಅಥವಾ ಹಣಕಾಸಿನ ಸಲಹೆ ಅಲ್ಲ. ತೀರ್ಪುಗಳು ಹೊರಗಿನ AI ಸೇವೆಯಿಂದ ಬರುತ್ತವೆ ಮತ್ತು ತಪ್ಪಾಗಬಹುದು, ಆದ್ದರಿಂದ ಮುಖ್ಯ ನಿರ್ಧಾರಗಳಿಗೆ ಅವುಗಳನ್ನು ನಂಬಬೇಡಿ.",
    "terms.contentTitle": "ನಿಮ್ಮ ವಿಷಯ",
    "terms.content":
      "ನೀವು ಬರೆದದ್ದು ನಿಮ್ಮದೇ ಆಗಿರುತ್ತದೆ. ಸೇವೆಯನ್ನು ನಡೆಸಲು ಬೇಕಾದಷ್ಟು ಮಟ್ಟಿಗೆ ಅದನ್ನು ಬಳಸಲು ನೀವು ನಮಗೆ ಅನುಮತಿ ನೀಡುತ್ತೀರಿ: ಸಂಗ್ರಹಿಸಲು, ಹೆಸರುಗಳನ್ನು ತೆಗೆಯಲು, ತೀರ್ಪು ಕೊಡಿಸಲು ಮತ್ತು ನೀವು ಹಂಚಿಕೊಂಡ ಕಡೆ ತೋರಿಸಲು. ಹಂಚಿಕೊಳ್ಳುವ ಹಕ್ಕು ನಿಮಗಿಲ್ಲದ ಇತರರ ಖಾಸಗಿ ಮಾಹಿತಿಯನ್ನು ಕಳುಹಿಸಬೇಡಿ, ಮತ್ತು ಕಾನೂನುಬಾಹಿರ, ಬೆದರಿಕೆಯ ಅಥವಾ ನಿಂದನೆಯ ಯಾವುದನ್ನೂ ಕಳುಹಿಸಬೇಡಿ.",
    "terms.purchasesTitle": "ಖರೀದಿಗಳು",
    "terms.purchases":
      "ಕ್ರೆಡಿಟ್ ಪ್ಯಾಕ್‌ಗಳು ಮತ್ತು ಮಾಸಿಕ ಪ್ಲಾನ್ ಅನ್ನು App Store ಅಥವಾ Google Play ಮೂಲಕ ಖರೀದಿಸಲಾಗುತ್ತದೆ. ಮಾಸಿಕ ಪ್ಲಾನ್ ಅನ್ನು ನವೀಕರಣಕ್ಕೆ ಕನಿಷ್ಠ 24 ಗಂಟೆ ಮೊದಲು ಸ್ಟೋರ್‌ನ ಚಂದಾ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ನೀವು ರದ್ದುಮಾಡುವವರೆಗೆ ಅದು ಪ್ರತಿ ತಿಂಗಳು ತಾನಾಗಿ ನವೀಕರಣಗೊಳ್ಳುತ್ತದೆ. ಮರುಪಾವತಿಗಳು Apple ಅಥವಾ Google ಮೂಲಕ ನಡೆಯುತ್ತವೆ. ಕ್ರೆಡಿಟ್‌ಗಳಿಗೆ ನಗದು ಮೌಲ್ಯವಿಲ್ಲ.",
